package com.quincaisoft.reporting.application;
import com.quincaisoft.reporting.api.ReportingService;import com.quincaisoft.reporting.domain.ReportRules;import com.quincaisoft.shared.*;
import org.jooq.*;import org.jooq.impl.DSL;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;import java.math.BigDecimal;
@Service public class DefaultReportingService implements ReportingService {
 private final DSLContext sql;private final ScopedTransactions tx;
 public DefaultReportingService(DSLContext sql,ScopedTransactions tx){this.sql=sql;this.tx=tx;}
 private record Spec(String view,String title,String basis,List<String> columns,List<String> totals,String order,boolean dated,String permission){}
 private static final Map<String,Spec> SPECS=Map.ofEntries(
  Map.entry("customer-custody",new Spec("document_custody_v1","Customer-owned goods awaiting pickup","Current recognized customer custody, collected and remaining quantities; mixed units are not summed and frozen acquisition cost is not disclosed",List.of("id","sale_id","customer_id","party","business_date","status","product_id","sku","description","base_unit","warehouse_id","quantity_milli","collected_milli","remaining_milli"),List.of(),"id",false,"inventory:read")),
  Map.entry("recalls",new Spec("document_recall_v1","Approved lot recall register","Approved recall business dates and current lot quarantine; lot quarantine can span multiple recalls and is not summed",List.of("id","business_date","status","lot_id","lot_number","product_id","sku","description","base_unit","warehouse_id","quantity_milli","quarantined_milli","reason","evidence_reference","approved_by"),List.of(),"id",true,"inventory:read")),
  Map.entry("supplier-payables",new Spec("report_supplier_payables_v1","Supplier invoice payable balances","Current invoice original less settled amount, including fully settled invoices; supplier advances remain separate; no inferred due dates or ageing",List.of("id","supplier_id","supplier_name","business_date","supplier_reference","original_xaf","paid_xaf","outstanding_xaf"),List.of("original_xaf","paid_xaf","outstanding_xaf"),"id",false,"finance:read")),
  Map.entry("posted-sales",new Spec("report_posted_sales_v1","Posted sales and recognized cost","Posted original sales by business date; subsequent returns are not netted",List.of("id","business_date","customer_id","status","total_xaf","cost_xaf","margin_xaf"),List.of("total_xaf","cost_xaf","margin_xaf"),"id",true,"finance:read")),
  Map.entry("sales-register",new Spec("report_posted_sales_v1","Posted sales register","Posted original invoice amounts; does not infer collections or net returns",List.of("id","business_date","customer_id","status","total_xaf"),List.of("total_xaf"),"id",true,"sales:read")),
  Map.entry("sales-lines",new Spec("report_sales_lines_v1","Posted sales line drilldown","Original posted invoice lines, by sale business date; no aggregation across mixed product units or return netting",List.of("line_id","sale_id","business_date","customer_id","product_id","quantity_milli","unit_price_xaf","line_total_xaf"),List.of("line_total_xaf"),"line_id",true,"sales:read")),
  Map.entry("stock",new Spec("report_stock_v1","Merchant serviceable stock","Current merchant-serviceable positions; not full physical/custody inventory",List.of("warehouse_id","product_id","sku","name","base_unit","quantity_milli","reserved_milli","allocated_milli","available_milli","value_xaf"),List.of("value_xaf"),"product_id",false,"inventory:read")),
  Map.entry("receivables",new Spec("report_receivable_v1","Outstanding customer sales","Current per-sale receivable projection; not credit/deposit liabilities or aging",List.of("sale_id","customer_id","business_date","outstanding_xaf"),List.of("outstanding_xaf"),"sale_id",false,"finance:read")),
  Map.entry("cash",new Spec("report_cash_v1","Cash session reconciliation","Session business date; expected cash equals opening plus immutable cash movements",List.of("id","till_code","business_date","status","opening_xaf","movement_xaf","expected_xaf","counted_xaf","variance_xaf"),List.of("opening_xaf","movement_xaf","expected_xaf"),"id",true,"cash:read")),
  Map.entry("provider-intents",new Spec("report_provider_intent_v1","Provider intent status","Requests are not collected money; sandbox EUR and live XAF are never summed",List.of("id","sale_id","business_date","environment","currency","status","amount","journal_id"),List.of(),"id",true,"tenders:read")),
  Map.entry("returns",new Spec("report_returns_v1","Posted customer credit notes","Posted return credit by return business date; customer-credit liability is distinct from cash refunds",List.of("id","sale_id","customer_id","business_date","credit_xaf","customer_credit_xaf"),List.of("credit_xaf","customer_credit_xaf"),"id",true,"returns:read")),
  Map.entry("deposits",new Spec("report_deposit_v1","Customer deposit liability","Current original deposit less allocated and refunded amounts; liabilities are not netted against receivables",List.of("id","customer_id","original_xaf","allocated_xaf","refunded_xaf","remaining_xaf"),List.of("original_xaf","allocated_xaf","refunded_xaf","remaining_xaf"),"id",false,"tenders:read")),
  Map.entry("expenses",new Spec("report_expense_v1","Posted expense register","Paid expenses by business date with payment-fact drilldown; not a category profitability model",List.of("id","business_date","category","payee","amount_xaf","paid_fact_id"),List.of("amount_xaf"),"id",true,"expenses:read")),
  Map.entry("purchase-progress",new Spec("report_purchase_progress_v1","Purchase line receipt progress","Per-product ordered less received quantities by purchase business date; units are never combined; drafts labeled explicitly",List.of("line_id","purchase_id","business_date","status","party","product_id","description","base_unit","quantity_milli","received_milli","remaining_milli","line_total_xaf"),List.of("line_total_xaf"),"line_id",true,"purchasing:read")),
  Map.entry("supplier-invoices",new Spec("report_supplier_invoice_v1","Matched supplier invoices","Posted matched invoice amounts by invoice business date; not open AP aging or supplier payments",List.of("id","receipt_id","supplier_id","business_date","supplier_reference","total_xaf"),List.of("total_xaf"),"id",true,"purchasing:read")),
  Map.entry("stock-movements",new Spec("report_stock_movement_v1","Immutable stock movement card","Movement occurrence date in the branch timezone; not original source business date; signed value movements, mixed units unsummed",List.of("id","warehouse_id","product_id","business_date","occurred_at","quantity_milli","value_xaf","operation_id","reason"),List.of("value_xaf"),"id",true,"inventory:read")),
  Map.entry("count-variances",new Spec("report_count_variance_v1","Posted count variances","Posted count output minus frozen source quantity; product units remain separate",List.of("id","business_date","source_product","description","base_unit","source_quantity_milli","output_quantity_milli","variance_milli"),List.of(),"id",true,"inventory:read")),
  Map.entry("journal-lines",new Spec("report_journal_line_v1","Operational journal lines","Immutable operational entries by business date; debit minus credit; not a certified statutory trial balance",List.of("line_id","journal_id","business_date","source_type","source_id","account_code","debit_xaf","credit_xaf","net_xaf"),List.of("debit_xaf","credit_xaf","net_xaf"),"line_id",true,"finance:read")),
  Map.entry("tender-facts",new Spec("report_tender_fact_v1","Immutable tender facts","Receipts, deposits, allocations, refunds and variances by business date; only signed cash delta is totaled to avoid double counting allocations",List.of("id","kind","business_date","customer_id","sale_id","deposit_id","cash_session_id","amount_xaf","cash_delta_xaf","journal_id"),List.of("cash_delta_xaf"),"id",true,"tenders:read")),
  Map.entry("audit-events",new Spec("report_audit_event_v1","Scoped audit events","Committed audit facts by recorded date in branch timezone; not proof of every access/export/fiscal-sequence control",List.of("id","business_date","recorded_at","actor_id","action","source_type","source_id","reason"),List.of(),"id",true,"audit:read")));
 public List<Definition> catalog(){return SPECS.entrySet().stream().sorted(Map.Entry.comparingByKey()).map(e->new Definition(e.getKey(),e.getValue().title,e.getValue().basis,e.getValue().columns,e.getValue().dated,e.getValue().permission)).toList();}
 public Report run(String code,LocalDate from,LocalDate to,int offset,int limit){ReportRules.page(offset,limit);Spec spec=SPECS.get(code);if(spec==null)throw new NoSuchElementException("Unknown implemented report code");authorize(spec.permission);if(spec.dated)ReportRules.range(from,to);else if(from!=null||to!=null)throw new IllegalArgumentException("This current-position report does not accept historical dates");
  return tx.execute(()->{var scope=TenantContext.current();
   boolean member=sql.fetchExists(DSL.selectOne().from(DSL.table("tenant_memberships")).where(DSL.field("tenant_id",UUID.class).eq(scope.tenantId())).and(DSL.field("company_id",UUID.class).eq(scope.companyId())).and(DSL.field("branch_id",UUID.class).eq(scope.branchId())).and(DSL.field("actor_id",UUID.class).eq(scope.actorId())).and(DSL.field("active",Boolean.class).eq(true)).and(DSL.field("authorization_epoch",Long.class).eq(TenantContext.authorizationEpoch())));
   if(!member)throw new org.springframework.security.access.AccessDeniedException("Current reporting membership required");
   Condition predicate=DSL.field("tenant_id",UUID.class).eq(scope.tenantId()).and(DSL.field("company_id",UUID.class).eq(scope.companyId())).and(DSL.field("branch_id",UUID.class).eq(scope.branchId()));if(spec.dated)predicate=predicate.and(DSL.field("business_date",LocalDate.class).between(from,to));
   var fields=new ArrayList<SelectFieldOrAsterisk>();spec.columns.forEach(c->fields.add(DSL.field(DSL.name(c))));spec.totals.forEach(c->fields.add(DSL.sum(DSL.field(DSL.name(c),BigDecimal.class)).over().as("__total_"+c)));var fetched=sql.select(fields).from(DSL.name(spec.view)).where(predicate).orderBy(DSL.field(DSL.name(spec.order)),DSL.field(DSL.name(spec.columns.getFirst()))).limit(limit+1).offset(offset).fetch();boolean more=fetched.size()>limit;
   List<List<String>> rows=fetched.stream().limit(limit).map(row->spec.columns.stream().map(c->exact(row.get(c))).toList()).toList();var totals=new LinkedHashMap<String,String>();
   if(!fetched.isEmpty())for(String column:spec.totals){BigDecimal sum=fetched.getFirst().get("__total_"+column,BigDecimal.class);totals.put(column,sum==null?"0":sum.toBigIntegerExact().toString());}
   return new Report(code,spec.basis,scope.tenantId(),scope.companyId(),scope.branchId(),from,to,Instant.now(),spec.columns,rows,Map.copyOf(totals),offset,limit,more);
  });}
 private static void authorize(String permission){var a=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated()||a.getAuthorities().stream().noneMatch(x->x.getAuthority().equals(permission)||x.getAuthority().equals("SCOPE_"+permission)))throw new org.springframework.security.access.AccessDeniedException("Report source permission required: "+permission);}
 private static String exact(Object value){if(value==null)return "";if(value instanceof BigDecimal n)return n.toBigIntegerExact().toString();return value.toString();}
 public String csv(Report report){var lines=new ArrayList<String>();lines.add(report.columns().stream().map(ReportRules::cell).collect(java.util.stream.Collectors.joining(",")));for(var row:report.rows())lines.add(row.stream().map(ReportRules::cell).collect(java.util.stream.Collectors.joining(",")));return String.join("\r\n",lines)+"\r\n";}
}
